+// A move job moves its sources one by one, and rewriting the clipboard after each of them takes long and floods
+// clipboard managers when thousands of files were cut. So the job's updater collects where its sources went,
+// and updates the clipboard once.
+static QList<ClipboardUpdater *> s_moveUpdaters;
+
+bool ClipboardUpdater::isMovedByRunningJob(const QUrl &url)
+{
+    return std::any_of(s_moveUpdaters.cbegin(), s_moveUpdaters.cend(), [&url](const ClipboardUpdater *updater) {
+        return updater->m_srcUrls.contains(url);
+    });
+}
+
+void ClipboardUpdater::updateMovedUrls()
+{
+    if (!s_moveUpdaters.removeOne(this) || m_movedUrls.isEmpty()) {
+        return;
+    }
+
+    QClipboard *clipboard = QGuiApplication::clipboard();
+    auto mimeData = clipboard->mimeData();
+    if (!mimeData) {
+        return;
+    }
+
+    QList<QUrl> clipboardUrls = KUrlMimeData::urlsFromMimeData(mimeData);
+    bool update = false;
+    for (QUrl &url : clipboardUrls) {
+        if (const auto it = m_movedUrls.constFind(url); it != m_movedUrls.cend()) {
+            url = it.value();
+            update = true;
+        }
+    }
+
+    if (update) {
+        QMimeData *mime = new QMimeData();
+        mime->setUrls(clipboardUrls);
+        clipboard->setMimeData(mime);
+    }
+}
+
 void ClipboardUpdater::slotResult(KJob *job)
 {
+    // Even after an error or a cancel, as the sources moved until then are not there anymore
+    if (!m_srcUrls.isEmpty()) {
+        updateMovedUrls();
+        return;
+    }
+
     if (job->error()) {
         return;
     }

     switch (m_mode) {
     case JobUiDelegateExtension::UpdateContent:
+        if (auto fileCopyJob = qobject_cast<FileCopyJob *>(job); fileCopyJob && isMovedByRunningJob(fileCopyJob->srcUrl())) {
+            break;
+        }
         updateUrlsInClipboard(job);
         break;
     case JobUiDelegateExtension::OverwriteContent:
         overwriteUrlsInClipboard(job);
         break;
     case JobUiDelegateExtension::RemoveContent:
+        // A move to another file system deletes each source after copying it
+        if (auto simpleJob = qobject_cast<SimpleJob *>(job); simpleJob && isMovedByRunningJob(simpleJob->url())) {
+            break;
+        }
         removeUrlsFromClipboard(job);
         break;
     }
@@ -159,6 +194,10 @@ void ClipboardUpdater::setMode(JobUiDelegateExtension::ClipboardUpdaterMode mode

 void ClipboardUpdater::update(const QUrl &srcUrl, const QUrl &destUrl)
 {
+    if (isMovedByRunningJob(srcUrl)) {
+        return;
+    }
+
     QClipboard *clipboard = QGuiApplication::clipboard();
     auto mimeData = clipboard->mimeData();
     if (mimeData && mimeData->hasUrls()) {
@@ -179,6 +218,29 @@ ClipboardUpdater::ClipboardUpdater(Job *job, JobUiDelegateExtension::ClipboardUp
 {
     Q_ASSERT(job);
     connect(job, &KJob::result, this, &ClipboardUpdater::slotResult);
+
+    if (auto copyJob = qobject_cast<CopyJob *>(job); copyJob && mode == JobUiDelegateExtension::UpdateContent) {
+        const QList<QUrl> srcUrls = copyJob->srcUrls();
+        m_srcUrls = QSet<QUrl>(srcUrls.cbegin(), srcUrls.cend());
+        auto addMovedUrl = [this](const QUrl &from, const QUrl &to) {
+            if (m_srcUrls.contains(from)) {
+                m_movedUrls.insert(from, to);
+            }
+        };
+        connect(copyJob, &CopyJob::copyingDone, this, [addMovedUrl](KIO::Job *, const QUrl &from, const QUrl &to) {
+            addMovedUrl(from, to);
+        });
+        connect(copyJob, &CopyJob::copyingLinkDone, this, [addMovedUrl](KIO::Job *, const QUrl &from, const QString &, const QUrl &to) {
+            addMovedUrl(from, to);
+        });
+        s_moveUpdaters.append(this);
+    }
+}
+
+ClipboardUpdater::~ClipboardUpdater()
+{
+    // A job killed quietly emits no result
+    updateMovedUrls();
 }

